-- ONLY after exact baseline parity: all ten schema fingerprints must match.
-- Registers historical versions represented by the schema snapshot; does not replay them.
DO $verify$ DECLARE actual jsonb; BEGIN
 SELECT schema_fingerprint INTO actual FROM (select jsonb_build_object('constraints',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select c.relname,k.conname,k.contype,pg_get_constraintdef(k.oid,true) as definition from pg_constraint k join pg_class c on c.oid=k.conrelid where c.relnamespace='public'::regnamespace order by case when k.contype='f' then 1 else 0 end,k.oid) x),'grants',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select 'relation' as kind,c.relname as name,c.relkind::text as subtype,null::text as args,case when acl.grantee=0 then 'PUBLIC' else pg_get_userbyid(acl.grantee) end as grantee,acl.privilege_type,acl.is_grantable from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) acl where c.relnamespace='public'::regnamespace and c.relkind in ('r','v','S') union all select 'function',p.proname,'f',pg_get_function_identity_arguments(p.oid),case when acl.grantee=0 then 'PUBLIC' else pg_get_userbyid(acl.grantee) end,acl.privilege_type,acl.is_grantable from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl where p.pronamespace='public'::regnamespace and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') order by 1,2,5,6) x),'indexes',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select c.relname,ic.relname as index_name,pg_get_indexdef(i.indexrelid) as ddl,i.indisreplident,i.indisvalid from pg_index i join pg_class c on c.oid=i.indrelid join pg_class ic on ic.oid=i.indexrelid where c.relnamespace='public'::regnamespace and not exists(select 1 from pg_constraint k where k.conindid=i.indexrelid) order by i.indexrelid) x),'policies',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select * from pg_policies where schemaname='public' order by tablename,policyname) x),'routines',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select p.proname,pg_get_function_identity_arguments(p.oid) as args,pg_get_functiondef(p.oid) as ddl,pg_get_userbyid(p.proowner) as owner from pg_proc p where p.pronamespace='public'::regnamespace and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') order by p.oid) x),'sequences',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select c.relname,format_type(s.seqtypid,null) as type,s.seqstart::text,s.seqincrement::text,s.seqmax::text,s.seqmin::text,s.seqcache::text,s.seqcycle, d.deptype, t.relname as owner_table,a.attname as owner_column from pg_sequence s join pg_class c on c.oid=s.seqrelid left join pg_depend d on d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype in ('a','i') left join pg_class t on t.oid=d.refobjid left join pg_attribute a on a.attrelid=t.oid and a.attnum=d.refobjsubid where c.relnamespace='public'::regnamespace order by c.oid) x),'tables',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select c.relname,c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions, pg_get_userbyid(c.relowner) as owner, jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'collation',case when a.attcollation<>ty.typcollation then a.attcollation::regcollation::text end) order by a.attnum) as columns from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped join pg_type ty on ty.oid=a.atttypid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where c.relnamespace='public'::regnamespace and c.relkind='r' group by c.oid order by c.oid) x),'triggers',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select n.nspname,c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true) as ddl from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where not t.tgisinternal and (c.relnamespace='public'::regnamespace or p.pronamespace='public'::regnamespace) order by t.oid) x),'types',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select t.typname, jsonb_agg(e.enumlabel order by e.enumsortorder) as labels from pg_type t join pg_enum e on e.enumtypid=t.oid where t.typnamespace='public'::regnamespace group by t.oid,t.typname order by t.oid) x),'views',(select jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb)::text)) from (select c.relname,c.reloptions,pg_get_viewdef(c.oid,true) as definition,pg_get_userbyid(c.relowner) as owner from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='v' order by c.oid) x)) as schema_fingerprint) f;
 IF actual IS DISTINCT FROM '{"constraints":{"count":808,"md5":"f3a9f37189d20ad374ccc1c3e7dc5a1e"},"grants":{"count":6282,"md5":"a7c4e4b83be1334ca26aaed12244d1fc"},"indexes":{"count":608,"md5":"15c0dc473ec1bfa58acdfc0723c766bf"},"policies":{"count":427,"md5":"6487d1a37e15df1b7c874a498cf02deb"},"routines":{"count":50,"md5":"4321c9bc3d36b86691b7ac333b41de5f"},"sequences":{"count":7,"md5":"931c5509e6c389fd1a6e77175537decb"},"tables":{"count":244,"md5":"6850f244772a1c08c838f4f6274d3e5c"},"triggers":{"count":17,"md5":"3b8a87c23d6c197dee974c3d456da80e"},"types":{"count":9,"md5":"bd4bab8ff6c938e731606fd686185ade"},"views":{"count":12,"md5":"fccf2ad28c35dfe881ba1ba34c9bfbd7"}}'::jsonb THEN RAISE EXCEPTION 'Baseline parity failed; refusing history reconciliation'; END IF;
END $verify$;
ON CONFLICT(version) DO NOTHING;
